/*
equation index: 16026
indexNonlinear: 14
type: NONLINEAR

vars: {battery.v, inverter.inverter.V_abs}
eqns: {16015, 16016, 16017, 16018, 16019, 16020, 16021, 16022, 16023, 16025, 16024}
*/
void BobLib_Experiments_Standards_VehicleSim_eqFunction_16026(DATA *data, threadData_t *threadData)
{
  const int equationIndexes[2] = {1,16026};
  int retValue;
  infoStreamPrint(OMC_LOG_DT, 0, "Solving nonlinear system 16026 (STRICT TEARING SET if tearing enabled) at time = %18.10e", data->localData[0]->timeValue);
  /* get old value */
  data->simulationInfo->nonlinearSystemData[14].nlsxOld[0] = (data->localData[0]->realVars[data->simulationInfo->realVarsIndex[2263]] /* battery.v variable */);
  data->simulationInfo->nonlinearSystemData[14].nlsxOld[1] = (data->localData[0]->realVars[data->simulationInfo->realVarsIndex[10218]] /* inverter.inverter.V_abs variable */);
  retValue = solve_nonlinear_system(data, threadData, 14);
  /* check if solution process was successful */
  if (retValue > 0){
    const int indexes[2] = {1,16026};
    throwStreamPrintWithEquationIndexes(threadData, omc_dummyFileInfo, indexes, "Solving non-linear system 16026 failed at time=%.15g.\nFor more information please use -lv LOG_NLS.", data->localData[0]->timeValue);
  }
  /* write solution */
  (data->localData[0]->realVars[data->simulationInfo->realVarsIndex[2263]] /* battery.v variable */) = data->simulationInfo->nonlinearSystemData[14].nlsx[0];
  (data->localData[0]->realVars[data->simulationInfo->realVarsIndex[10218]] /* inverter.inverter.V_abs variable */) = data->simulationInfo->nonlinearSystemData[14].nlsx[1];
  threadData->lastEquationSolved = 16026;
}
